INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 31, 'theory', 'Квиз: диагностика');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 31, 0, 'Что считает средняя загрузка (load average) в Linux?', '["Только процент занятого процессора", "Задачи в очереди на процессор и в непрерываемом сне (обычно ожидание диска)", "Только процессы, читающие или пишущие на диск", "Число потоков в состоянии сна"]', 1, 'По справочнику proc загрузка — это число задач в очереди выполнения (R) или ждущих диска (D). Поэтому она может быть высокой при простаивающем процессоре.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 31, 1, 'Какой показатель в /proc/meminfo лучше всего оценивает память, доступную новым программам без подкачки?', '["MemFree", "Cached", "Buffers", "MemAvailable"]', 3, 'MemAvailable (с ядра 3.14) учитывает кэш файлов и возвращаемые слэбы. MemFree занижает доступное, потому что ядро держит остаток под кэш.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 31, 2, 'Что означает первая строка вывода vmstat 1?', '["Средние значения с момента загрузки для счётчиков в секунду и проценты процессора", "Измерение за последнюю секунду", "Максимумы за сутки", "Значения только для первого ядра"]', 0, 'Очередь r и память в первой строке мгновенные, а скорости и проценты усреднены с загрузки. Поэтому диагноз ставят по следующим строкам.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 31, 3, 'Внутри виртуальной машины top показывает st около 20 процентов. Что это значит?', '["Процессы гостя заняли процессор на 20 процентов", "Диск гостя перегружен", "Гипервизор отдавал процессор другим машинам, пока vCPU ждал, то есть хост перегружен", "У гостя не хватает памяти"]', 2, 'Steal — время, когда виртуальный процессор был готов работать, но физического не получил. Лечить надо на хосте: уменьшить переподписку или переселить машины.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 31, 4, 'Почему %util около 100 в iostat -x не всегда доказывает насыщение NVMe-диска?', '["Потому что %util считает только операции записи", "Потому что показатель говорит лишь, что запросы были в работе почти всё время, а устройство обслуживает их параллельно", "Потому что для NVMe %util не вычисляется", "Потому что он усреднён с момента загрузки"]', 1, '%util — доля времени, когда запросы были выданы устройству. У параллельных устройств оно не отражает предела, поэтому смотрят ожидание и aqu-sz.');
